return {
    { n = 1, q = "requiredPermissions isn't working (trackingAccess, httpAccess, chatAccess)", a = "Leave requiredPermissions empty and list the permission under optionalPermissions instead, then grant it from the console: \"requiredPermissions\": [ ], \"optionalPermissions\": [ \"trackingAccess\" ], Known issue: \"requiredPermissions\" doesn't currently work. If you need something like chatAccess, put it in \"optionalPermissions\".", freq = "Often (4+ askers on Oct 19, again Oct 20). Also a known issue.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19; #api-launch-known-issues, Oct 19.", code = { "\"requiredPermissions\": [ ], \"optionalPermissions\": [ \"trackingAccess\" ]," },
