    { n = 2, q = "How do I grant a permission such as httpAccess in dev? ppe prints nothing.", a = "Run prf (or restart the client) after editing the manifest, then run these in order: ppr [pluginname] ppe [pluginname] httpAccess prl [pluginname] prl depends on what the plugin needs, but it's a good habit. ppr is needed to set up the permissions until the permission pop-ups are live. A permissions prompt is coming in the future, which will remove the need for ppr and ppe in the console.", freq = "Several (Oct 19, Oct 19 evening).", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19.", code = { "ppr [pluginname]", "ppe [pluginname] httpAccess", "prl [pluginname]" },
