    { n = 6, q = "Can I reload my plugin without restarting the client? What do prf and prl do?", a = "Just save the file, run prl [pluginname] and it reloads. Double-clicking the plugin's checkbox in the plugin menu also reloads it. Use prf after manifest changes. Up arrow in the console recalls earlier commands. Open the console with Alt + (backtick). displayfps shows FPS for performance testing.", freq = "Often.", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 19; #plugin-support, Oct 19.", code = { "prl [pluginname]", "prf", "displayfps" },
