    { n = 7, q = "Is there an event for the plugin enable/disable button? I need to clean up when it's disabled.", a = "The button only runs the startup and shutdown lifecycle, so clean up in PluginShutdown. Docs: https://developer.runescape.com/rs/core/clientoptions.html?h=pluginShutdown#example Example: turn login-screen music off while the plugin is active and restore it on shutdown.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 20.", code = { "PluginShutdown" },
      posts = {
