    { n = 8, q = "Dependency error: \"Failed to resolve dependencies. Missing dependency rsprite for plugin\"", a = "Check the manifest structure: https://developer.runescape.com/rs/structure.html#manifest. Also make sure you used the rsprite release, not the whole repo. Pointed out the manifest is not a package.json (fields from npm don't apply). No definitive fix was posted.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 21.", code = {  },
