    { n = 9, q = "Can I depend on another plugin by name, or only by mod.io ID?", a = "A string name works only for local dev, with the plugin in your plugins folder: { \"zyklib\": \"zyklib\" } For submission it must be the mod.io ID: { \"zyklib\": 123456 } Dependencies are globals named by the dependency key, so you don't require them. Local dependencies work locally only; mod.io dependencies work both locally and live. You access them by the key name you gave.", freq = "Several (zyklib thread).", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 20; #dev-questions, Oct 21.", code = { "{ \"zyklib\": \"zyklib\" }", "{ \"zyklib\": 123456 }" },
      posts = {
