        { role = "A", user = "Unknown user", tag = "community", date = "Oct 20", lines = { "A string name works only for local dev, with the plugin in your plugins folder: { \"zyklib\": \"zyklib\" }", "For submission it must be the mod.io ID: { \"zyklib\": 123456 }", "Dependencies are globals named by the dependency key, so you don't require them." } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 21", lines = { "Local dependencies work locally only; mod.io dependencies work both locally and live. You access them by the key name you gave." } } } },
    { n = 10, q = "Does contactEmailAddress have to be in plugin.json? Can I keep it out of the public listing?", a = "It's mostly used if you go AWOL and Jagex needs you to update or fix something. I made a new email just for plugin things and forward it. The docs say it is a legal requirement, and recommend a different address from the one you use for mod.io. Not confirmed by staff whether it's shown publicly.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 21.", code = {  },
      posts = {
        { role = "Q", user = "Aerrek", tag = "community", date = "Oct 21", lines = { "Can contactEmailAddress in plugin.json be left out? I'd like to keep my email out of the public listing." } },
        { role = "A", user = "TheJoshJ", tag = "community", date = "Oct 21", lines = { "It's mostly used if you go AWOL and Jagex needs you to update or fix something. I made a new email just for plugin things and forward it.", "The docs say it is a legal requirement, and recommend a different address from the one you use for mod.io. Not confirmed by staff whether it's shown publicly." } } } },
    { n = 11, q = "My plugin turns itself off when I lobby, change world or log in. How do I test re-enable on login?", a = "Not in dev. Only plugins installed through mod.io re-enable on login. A bug with the equipped ammo sprite causes an error on first load, so the plugin doesn't enable. Fixed in an upcoming version.", freq = "Several (also Job Gauges disabling on login).", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19-22.", code = {  },
      posts = {
        { role = "Q", user = "Wildefires", tag = "community", date = "Oct 21", lines = { "My plugin gets turned off when I lobby and re-enter the game. Is there a way to keep it enabled?" } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 22", lines = { "Not in dev. Only plugins installed through mod.io re-enable on login." } },
        { role = "Q", user = "PIO", tag = "community", date = "Oct 21", lines = { "Anyone know why Job Gauges is disabled every time you log in?" } },
        { role = "A", user = "Ceren", tag = "community", date = "Oct 21", lines = { "A bug with the equipped ammo sprite causes an error on first load, so the plugin doesn't enable. Fixed in an upcoming version." } } } },
    { n = 12, q = "Dev client and main client share installed plugins and settings. Is there a fix?", a = "No fix yet. Hopefully a solution will come eventually. That's up to each plugin's developer. Early plugins were built around one shared set of settings or preset import and export. Settings are stored locally. Plugins can request permission to an account identifier (Player.GetTrackingID(), needs trackingAccess) and use it to save settings per account. Plugin files are shared between all clients, but this is an important issue, so thanks for raising it.", freq = "Several.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19-23; #general-technical, Oct 21.", code = { "Player.GetTrackingID()" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "My dev client and main client share the same installed plugins and settings. Is there a fix?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19", lines = { "No fix yet. Hopefully a solution will come eventually." } },
        { role = "Q", user = "Mental Demon", tag = "community", date = "Oct 21", lines = { "My two accounts share the same tile markers and menu swaps. Can settings be per account?" } },
        { role = "A", user = "Sudo Bash", tag = "community", date = "Oct 21", lines = { "That's up to each plugin's developer. Early plugins were built around one shared set of settings or preset import and export. Settings are stored locally." } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 21", lines = { "Plugins can request permission to an account identifier (Player.GetTrackingID(), needs trackingAccess) and use it to save settings per account." } },
        { role = "Q", user = "Kazter", tag = "community", date = "Oct 23", lines = { "Manually updating plugins while running several accounts at once made all the other clients crash." } },
        { role = "A", user = "Mod Jewel", tag = "Jagex staff", date = "Oct 23", lines = { "Plugin files are shared between all clients, but this is an important issue, so thanks for raising it." } } } },
    { n = 42, q = "Can a plugin have more than one .lua file?", a = "Yes, several plugins already do this. Example layout: https://codeberg.org/QuestHelper/QuestHelper/src/branch/main/src", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#dev-questions, Oct 23.", code = {  },
