    { n = 13, q = "Error: \"Failed to Create Layer (category=0 ID=4096) - invalid dynamic ID, expected a value between 0 and 4096\"", a = "Components aren't being cleaned up. See \"Valid ID Ranges\": https://developer.runescape.com/rs/ui/index.html?h=4096#components Call layer:DeleteAll() before a rebuild. The game destroys components your plugin creates on reload or shutdown, but not ones PrettyUI creates. Make your own empty layer, pass it to PrettyUI as the root, and call mainWindow:Destroy() in PluginShutdown. Prefer TOPLEVEL_V2__PLUGIN_BUILD_LAYER_TOP or TOPLEVEL_V2__PLUGIN_BUILD_LAYER_BOTTOM over TOPLEVEL_V2__GAME_AREA. Fixed it by destroying the SimpleView in PluginShutdown.", freq = "Several (noted as seen before).", section = "B. UI and PrettyUI", where = "#general-technical, Oct 21.", code = { "layer:DeleteAll()", "mainWindow:Destroy()", "PluginShutdown", "TOPLEVEL_V2__PLUGIN_BUILD_LAYER_TOP", "TOPLEVEL_V2__PLUGIN_BUILD_LAYER_BOTTOM", "TOPLEVEL_V2__GAME_AREA" },
      posts = {
        { role = "Q", user = "Siesta", tag = "community", date = "Oct 21", lines = { "Getting \"Failed to create Layer (category=0 ID=4096) - invalid dynamic ID\" after creating lots of sprites and tooltips with PrettyUI and running prl often." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 21", lines = { "Components aren't being cleaned up. See \"Valid ID Ranges\": https://developer.runescape.com/rs/ui/index.html?h=4096#components", "Call layer:DeleteAll() before a rebuild.", "The game destroys components your plugin creates on reload or shutdown, but not ones PrettyUI creates. Make your own empty layer, pass it to PrettyUI as the root, and call mainWindow:Destroy() in PluginShutdown.", "Prefer TOPLEVEL_V2__PLUGIN_BUILD_LAYER_TOP or TOPLEVEL_V2__PLUGIN_BUILD_LAYER_BOTTOM over TOPLEVEL_V2__GAME_AREA." } },
        { role = "A", user = "Siesta", tag = "community", date = "Oct 21", lines = { "Fixed it by destroying the SimpleView in PluginShutdown." } } } },
    { n = 14, q = "How do I create a headerless group box? SetHeaderLayout(0,0,0,0,0) still shows a header.", a = "Same here, also at 1440p. Looks like an API or tutorial issue; no fix posted. Probably just a mistake, no reason not to use either.", freq = "Several (3 reports incl. at 1440p, so not a resolution issue).", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 19.", code = { "SetHeaderLayout(0,0,0,0,0)" },
