    { n = 15, q = "Drag/move and drag-and-drop break on 2K/4K/QHD or high-DPI monitors (Job Gauges)", a = "Reported coordinates scale by 2x or 4x pixel density, so components don't follow the mouse 1:1. PrettyUI fixed this: look at its InterfaceMouse, which works out how far something moved once dragging starts. My workaround: track the hovered component at drop instead of using the native drag start and stop positions.", freq = "Several.", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 19; #general-technical, Oct 22.", code = { "InterfaceMouse" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Moving Job Gauges and drag-and-drop don't follow the mouse on my 2K/4K monitor." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 22", lines = { "Reported coordinates scale by 2x or 4x pixel density, so components don't follow the mouse 1:1. PrettyUI fixed this: look at its InterfaceMouse, which works out how far something moved once dragging starts." } },
        { role = "A", user = "TheJoshJ", tag = "community", date = "Oct 22", lines = { "My workaround: track the hovered component at drop instead of using the native drag start and stop positions." } } } },
