    { n = 17, q = "What is the \"value\" param for PrettyUI CheckboxButton?", a = "It's the value you receive in the changedValue variable, basically a label for the checkbox, so when several checkboxes share a callback you know which one changed. Instead of a plain true/false: if a value is set it is passed when ticked, otherwise you read its selected state. It's mostly for defaults, and lets a group act like radio buttons that allow more than one choice.", freq = "Several.", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 20-21.", code = {  },
      posts = {
        { role = "Q", user = "4D Oranges", tag = "community", date = "Oct 21", lines = { "Can someone explain the purpose of the \"value\" parameter for a PrettyUI CheckboxButton?" } },
        { role = "A", user = "Polar", tag = "community", date = "Oct 21", lines = { "It's the value you receive in the changedValue variable, basically a label for the checkbox, so when several checkboxes share a callback you know which one changed." } },
        { role = "A", user = "Sudo Bash", tag = "community", date = "Oct 21", lines = { "Instead of a plain true/false: if a value is set it is passed when ticked, otherwise you read its selected state. It's mostly for defaults, and lets a group act like radio buttons that allow more than one choice." } } } },
    { n = 18, q = "Can I make a PrettyUI window transparent but still movable (show only sprites)?", a = "You can grab the PrettyUI window's root prop and modify it. Or use native sprites in a native panel. If all you care about is sprites, you could use rsprite.", freq = "Once.", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 22.", code = {  },
      posts = {
        { role = "Q", user = "Elling", tag = "community", date = "Oct 22", lines = { "Can I make a PrettyUI window transparent but keep a small point to move it, and only show sprites?" } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 22", lines = { "You can grab the PrettyUI window's root prop and modify it. Or use native sprites in a native panel." } },
        { role = "A", user = "draconis imp", tag = "community", date = "Oct 22", lines = { "If all you care about is sprites, you could use rsprite." } } } },
    { n = 19, q = "ui.Interfaces:GetComponent() returns the previous clue-scroll text, not the current text", a = "The inventory update fires before the server sets the text. Workaround: 1. In InventoryAdded / InventoryUpdated, set a flag. 2. Subscribe to the modal's ui.Hook.ONSUBCHANGE and mark the interface ready there. 3. On the next Event.Logic tick, read id.Component.TRAIL_REWARD__CURRENT_VALUE and Inventory.Find(id.Inv.TRAIL_REWARDINV). It did work. For prices, a GE price library gives more accurate values.", freq = "Once, long thread.", section = "B. UI and PrettyUI", where = "#general-technical, Oct 21.", code = { "ui.Hook.ONSUBCHANGE", "Event.Logic", "id.Component.TRAIL_REWARD__CURRENT_VALUE", "Inventory.Find(id.Inv.TRAIL_REWARDINV)" },
      posts = {
        { role = "Q", user = "Siesta", tag = "community", date = "Oct 21", lines = { "Why does ui.Interfaces:GetComponent() not get the current value when reading the clue scroll reward UI? It shows the previous value. I'm reading it in InventoryAdded." } },
        { role = "A", user = "Polar", tag = "community", date = "Oct 21", lines = { "The inventory update fires before the server sets the text. Workaround:", "1. In InventoryAdded / InventoryUpdated, set a flag.", "2. Subscribe to the modal's ui.Hook.ONSUBCHANGE and mark the interface ready there.", "3. On the next Event.Logic tick, read id.Component.TRAIL_REWARD__CURRENT_VALUE and Inventory.Find(id.Inv.TRAIL_REWARDINV)." } },
        { role = "A", user = "Siesta", tag = "community", date = "Oct 21", lines = { "It did work." } },
        { role = "A", user = "TheJoshJ", tag = "community", date = "Oct 21", lines = { "For prices, a GE price library gives more accurate values." } } } },
    { n = 20, q = "Why are chat event fields read-only? Can I modify chat?", a = "Chat isn't writable. You can hide messages and re-post them through the plugin chat type, which needs chatAccess. Setting content to an empty string leaves a blank line, and nil doesn't work.", freq = "Once.", section = "B. UI and PrettyUI", where = "#general-technical, Oct 19.", code = { "chatAccess" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Why are chat event fields read-only? Can I modify chat messages?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19", lines = { "Chat isn't writable. You can hide messages and re-post them through the plugin chat type, which needs chatAccess.", "Setting content to an empty string leaves a blank line, and nil doesn't work." } } } },
    { n = 21, q = "Two listeners on Event.NPCEntityAdded: only the first gets usable data (isValid=false, name nil)", a = "Try returning a value from the handler. Most events don't care about return values. EntityDraw docs require one, and the docs should say for the others. Reported in game as a bug; not resolved.", freq = "Once, with multiple confirmers.", section = "C. API usage and events", where = "#plugin-support, Oct 20.", code = { "Event.NPCEntityAdded" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 20", lines = { "With two listeners on Event.NPCEntityAdded, only the first gets usable data; the second sees isValid=false and name nil." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 20", lines = { "Try returning a value from the handler." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 20", lines = { "Most events don't care about return values. EntityDraw docs require one, and the docs should say for the others. Reported in game as a bug; not resolved." } } } },
    { n = 22, q = "No os library. How do I time something (stopwatch)?", a = "There's no os at the moment, so you'd need to use the logic tick (Event.Logic).", freq = "Once.", section = "C. API usage and events", where = "#general-technical, Oct 22.", code = { "Event.Logic" },
