        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "The inventory docs say the property is valid, but that's nil. Is it something else?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19", lines = { "It's isValid; the docs are wrong (https://developer.runescape.com/rs/game/inventory.html#properties). Report it as a documentation issue." } } } },
    { n = 24, q = "What the API can't do yet (feature-gap questions)", a = "Player animations can't be swapped yet. Drop tables are server-side; use wiki data in a static Lua file. There's no direct kill-to-drop link. Item perks on gizmos and augmented gear aren't exposed. LocList.All() returns only scenery, not walls, roofs or ground decorations. Collision data isn't reliably exposed. Friends and FC lists are only readable while their window is open. Action bars can't be changed (moving or resizing click zones is restricted). Menu Entry Swapper limits are intentional: no Buy All, no default left-click Teleport or Drop. Rockertunity spawns aren't detectable: the sparkle is spotanim 7165, which plays over every rock, and spotanim support in the API is incomplete.", freq = "Often.", section = "C. API usage and events", where = "#plugin-support / #general-technical, Oct 19-22.", code = { "LocList.All()" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19-22", lines = { "Several people asked whether the API can do things like swap animations, read drop tables, read gizmo perks, detect Rockertunities or read walls." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19-22", lines = { "Player animations can't be swapped yet.", "Drop tables are server-side; use wiki data in a static Lua file. There's no direct kill-to-drop link.", "Item perks on gizmos and augmented gear aren't exposed.", "LocList.All() returns only scenery, not walls, roofs or ground decorations. Collision data isn't reliably exposed.", "Friends and FC lists are only readable while their window is open.", "Action bars can't be changed (moving or resizing click zones is restricted). Menu Entry Swapper limits are intentional: no Buy All, no default left-click Teleport or Drop." } },
        { role = "A", user = "Kris", tag = "community", date = "Oct 22", lines = { "Rockertunity spawns aren't detectable: the sparkle is spotanim 7165, which plays over every rock, and spotanim support in the API is incomplete." } } } },
    { n = 25, q = "Is there Lua IntelliSense / SDK support in VS Code?", a = "Use the community stubs: https://github.com/FriendlyDevelopment/runescape-api-stubs/ with a Lua extension (LuaLS). Put a .luarc.json in the opened plugin folder (adjust the stub path), and open the plugin's folder as the workspace: { \"workspace.library\": [ \"../runescape-api-stubs/types.lua\", \"../runescape-api-stubs/generated/\" ], \"workspace.checkThirdParty\": false }", freq = "Several.", section = "C. API usage and events", where = "#plugin-support, Oct 19-20.", code = { "{ \"workspace.library\": [ \"../runescape-api-stubs/types.lua\", \"../runescape-api-stubs/generated/\" ], \"workspace.checkThirdParty\": false }" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Is there Lua IntelliSense or an SDK for VS Code?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19-20", lines = { "Use the community stubs: https://github.com/FriendlyDevelopment/runescape-api-stubs/ with a Lua extension (LuaLS).", "Put a .luarc.json in the opened plugin folder (adjust the stub path), and open the plugin's folder as the workspace:", "{ \"workspace.library\": [ \"../runescape-api-stubs/types.lua\", \"../runescape-api-stubs/generated/\" ], \"workspace.checkThirdParty\": false }" } } } },
    { n = 26, q = "Is there a base64 / shared utility library? How do I share libraries between plugins?", a = "zyklib (https://codeberg.org/ZyklopMarco/runescape-api-zyklib, docs at zyklib.readthedocs.io) is in review. Copying it into your plugin is safer than a dynamic dependency, because a dynamic dependency can never break backward compatibility. See #9 for how to depend on it. Note (Oct 21): zyklib.async can crash the client; that bug is waiting on a Jagex fix.", freq = "Several.", section = "C. API usage and events", where = "#general-technical, Oct 20-21.", code = {  },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 20", lines = { "Is there a base64 or shared utility library? How do I share code between plugins?" } },
        { role = "A", user = "Zyklop Marco", tag = "community", date = "Oct 20", lines = { "zyklib (https://codeberg.org/ZyklopMarco/runescape-api-zyklib, docs at zyklib.readthedocs.io) is in review.", "Copying it into your plugin is safer than a dynamic dependency, because a dynamic dependency can never break backward compatibility. See #9 for how to depend on it.", "Note (Oct 21): zyklib.async can crash the client; that bug is waiting on a Jagex fix." } } } },
    { n = 27, q = "Which components are allowed in the API vs. cheat commands (getVar, getvarc)?", a = "Cheats don't work on live (https://developer.runescape.com/rs/cheats.html?h=getVar#getvar). Reading hidden client information (for example herb patch state when you're not nearby) wouldn't be approved. Reading loc data is allowed. !getvarc never worked.", freq = "Several.", section = "C. API usage and events", where = "#general-technical, Oct 20-22.", code = { "!getvarc" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 20", lines = { "Which things are allowed through the API versus cheat commands like getVar and getvarc?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 20", lines = { "Cheats don't work on live (https://developer.runescape.com/rs/cheats.html?h=getVar#getvar).", "Reading hidden client information (for example herb patch state when you're not nearby) wouldn't be approved. Reading loc data is allowed." } },
        { role = "A", user = "Friendliness", tag = "community", date = "Oct 22", lines = { "!getvarc never worked." } } } },
    { n = 41, q = "Messages added with Chat.AddMessage disappear when a friend logs in or out", a = "They were aware of it, I think, but not sure if it's intended. Haven't heard of that. (No fix found; re-add messages that must stay visible.)", freq = "Once.", section = "C. API usage and events", where = "#plugin-support, Oct 21.", code = { "Chat.AddMessage" },
      posts = {
        { role = "Q", user = "4D Oranges", tag = "community", date = "Oct 21", lines = { "Messages I add with Chat.AddMessage disappear when a friend logs in or out." } },
        { role = "A", user = "Friendliness", tag = "community", date = "Oct 21", lines = { "They were aware of it, I think, but not sure if it's intended." } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 21", lines = { "Haven't heard of that. (No fix found; re-add messages that must stay visible.)" } } } },
    { n = 43, q = "How do I link a Construction furniture item to its object (loc), e.g. Trellis?", a = "The link is a DBRow: find the row in the construction_house_furniture table whose column 4 is the item, then read column 2 for the loc. The loc also links back to the row. Column numbers aren't stable across updates; the docs example uses plain numbers: config.DBRow.INVENT_PERK_LOOTING:GetColumnValues(2) Docs: https://developer.runescape.com/rs/game/config/dbrowtype.html", freq = "Once.", section = "C. API usage and events", where = "#dev-questions, Oct 21.", code = { "config.DBRow.INVENT_PERK_LOOTING:GetColumnValues(2)" },
      posts = {
        { role = "Q", user = "laundrymat [BUN]", tag = "community", date = "Oct 21", lines = { "How do I map a Construction furniture item to its loc/config, for example Trellis?" } },
        { role = "A", user = "Polar, micha, Kris", tag = "community", date = "Oct 21", lines = { "The link is a DBRow: find the row in the construction_house_furniture table whose column 4 is the item, then read column 2 for the loc. The loc also links back to the row.", "Column numbers aren't stable across updates; the docs example uses plain numbers: config.DBRow.INVENT_PERK_LOOTING:GetColumnValues(2)", "Docs: https://developer.runescape.com/rs/game/config/dbrowtype.html" } } } },
    { n = 44, q = "What is DBTableType for, if I already have DBRows?", a = "A DBTable defines the structure; DBRows are the entries in it. You only need DBRows unless you want default values for columns a row doesn't set, or the column types.", freq = "Once.", section = "C. API usage and events", where = "#dev-questions, Oct 21, 9:39 PM.", code = {  },
      posts = {
        { role = "Q", user = "laundrymat [BUN]", tag = "community", date = "Oct 21", lines = { "What's the point of DBTableType?" } },
        { role = "A", user = "Polar", tag = "community", date = "Oct 21", lines = { "A DBTable defines the structure; DBRows are the entries in it. You only need DBRows unless you want default values for columns a row doesn't set, or the column types." } } } },
    { n = 28, q = "Sound alert volume below 1 is rounded and the sound doesn't play", a = "No official fix. Audio sliders live in game.options; a sample was shared that mutes login-screen music while a plugin runs.", freq = "Once.", section = "D. Sound", where = "#plugin-support, Oct 19-20; #general-technical, Oct 20.", code = { "game.options" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "For sound alerts, any float value below 1 seems to be rounded down, which disables the sound, so it only works at 1." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 20", lines = { "No official fix. Audio sliders live in game.options; a sample was shared that mutes login-screen music while a plugin runs." } } } },
    { n = 29, q = "How do I register my plugin / reserve its name and mod.io ID in the directory?", a = "Pinned how-to. Signing up reserves the plugin name and mod.io ID for you: /plugin signup adds your plugin to the directory. /plugin team add adds a team member. /plugin modio set sets your mod.io ID. Also: /plugin rename, /plugin transfer, /plugin list, /plugin delete, /plugin modio remove, /plugin team leave, /plugin team remove.", freq = "Once (pinned how-to).", section = "E. Packaging, mod.io, submission, directory", where = "#plugin-directory-how-to, Oct 19.", code = { "/plugin signup", "/plugin team add", "/plugin modio set" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "How do I register my plugin and reserve its name and mod.io ID?" } },
        { role = "A", user = "Friendlybot", tag = "community", date = "Oct 19", lines = { "Pinned how-to. Signing up reserves the plugin name and mod.io ID for you:", "/plugin signup adds your plugin to the directory.", "/plugin team add adds a team member. /plugin modio set sets your mod.io ID.", "Also: /plugin rename, /plugin transfer, /plugin list, /plugin delete, /plugin modio remove, /plugin team leave, /plugin team remove." } } } },
    { n = 30, q = "mod.io / Plugin Hub activation code email never arrives", a = "Try again, or try a different mail provider. It doesn't have to be the email on your RS account. Another email worked straight away. Known issue: using an email with a + sign can cause the Plugin Hub to crash.", freq = "Several (2+ users; one on a 4th attempt).", section = "E. Packaging, mod.io, submission, directory", where = "#general-technical, Oct 19-21; #api-launch-known-issues, Oct 19.", code = {  },
      posts = {
        { role = "Q", user = "Numbers", tag = "community", date = "Oct 21", lines = { "I'm not receiving the authentication email." } },
        { role = "A", user = "Friendliness", tag = "community", date = "Oct 21", lines = { "Try again, or try a different mail provider. It doesn't have to be the email on your RS account." } },
        { role = "A", user = "Numbers", tag = "community", date = "Oct 21", lines = { "Another email worked straight away." } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 19", lines = { "Known issue: using an email with a + sign can cause the Plugin Hub to crash." } } } },
    { n = 31, q = "How do I test a plugin before it's on mod.io? Can plugin info be user-configured (e.g. self-hosted API base URL)?", a = "Probably not allowed, but that's one for Mod Jewel. I use a fixed base URL in the manifest. Submitted plugins and plugin updates wait for Jagex review.", freq = "Once (self-host); the other is covered in #9.", section = "E. Packaging, mod.io, submission, directory", where = "#general-technical, Oct 20; #plugin-support, Oct 19.", code = {  },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 20", lines = { "Can users configure plugin info, like a self-hosted API base URL?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 20", lines = { "Probably not allowed, but that's one for Mod Jewel. I use a fixed base URL in the manifest." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19", lines = { "Submitted plugins and plugin updates wait for Jagex review." } } } },
    { n = 32, q = "AI / LLM policy: can LLMs be given the docs?", a = "That might be a holdover from before we went public. Policy will be updated. The restriction on the official docs was removed: official API docs and examples are OK. Don't upload code or docs you aren't licensed to, including other developers' plugins without their permission.", freq = "Several (many participants).", section = "E. Packaging, mod.io, submission, directory", where = "#plugin-support, Oct 19; #api-updates, Oct 20.", code = {  },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "The docs say not to give them to an AI. Is that still the rule?" } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 19", lines = { "That might be a holdover from before we went public. Policy will be updated." } },
        { role = "A", user = "Mod Jewel", tag = "Jagex staff", date = "Oct 20", lines = { "The restriction on the official docs was removed: official API docs and examples are OK. Don't upload code or docs you aren't licensed to, including other developers' plugins without their permission." } } } },
    { n = 45, q = "Will plugins that store data on a shared server be approved?", a = "They haven't announced a plan yet; still working out some kinks. I don't see why not. You'd probably be subject to this: https://developer.runescape.com/rs/submission/adequacy.html (not an official answer).", freq = "Once.", section = "E. Packaging, mod.io, submission, directory", where = "#dev-questions, Oct 21, 9:30 PM.", code = {  },
      posts = {
        { role = "Q", user = "butter", tag = "community", date = "Oct 21", lines = { "What's the status on getting plugins accepted that use a shared server to store data?" } },
        { role = "A", user = "TheJoshJ", tag = "community", date = "Oct 21", lines = { "They haven't announced a plan yet; still working out some kinks." } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 21", lines = { "I don't see why not. You'd probably be subject to this: https://developer.runescape.com/rs/submission/adequacy.html (not an official answer)." } } } },
    { n = 33, q = "Cheat commands (!give, teleport, getvar) don't work on dev/beta worlds", a = "Known issue: cheat commands on developer worlds are not working as intended. We're investigating (no ETA). The docs warn cheats are logged and abuse can lead to bans: don't spawn hidden or future items or spam items. When working, !setgroupironman 1 sets the account type for testing a shared bank. Shared a dev script that prints the cheat commands needed to complete an achievement.", freq = "Often (6+).", section = "F. Cheats and the dev environment", where = "#api-launch-known-issues, Oct 19; #plugin-support, #general-technical, Oct 19-22.", code = { "!setgroupironman 1" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Cheat commands like !give, teleport and getvar don't work on the dev world." } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 19", lines = { "Known issue: cheat commands on developer worlds are not working as intended. We're investigating (no ETA)." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19-22", lines = { "The docs warn cheats are logged and abuse can lead to bans: don't spawn hidden or future items or spam items. When working, !setgroupironman 1 sets the account type for testing a shared bank." } },
        { role = "A", user = "Polar", tag = "community", date = "Oct 22", lines = { "Shared a dev script that prints the cheat commands needed to complete an achievement." } } } },
    { n = 34, q = "Beta client won't launch from the news-post link / can't log in", a = "That link is broken; launch the beta from the docs link instead. To go back to live, close the game and launcher and relaunch normally.", freq = "Several.", section = "F. Cheats and the dev environment", where = "#plugin-support, #general-technical, Oct 19-20.", code = {  },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "The beta client won't launch from the news-post link." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19", lines = { "That link is broken; launch the beta from the docs link instead. To go back to live, close the game and launcher and relaunch normally." } } } },
    { n = 35, q = "Game crashes after installing/updating plugins (Oct 21)", a = "Really bad timing: they're having issues with plugins right now and are working on a fix. A hotfix was reverted. If you updated plugins between 15:00 and 16:00 BST, delete all folders (for example 6398181) under C:\\ProgramData\\Jagex\\RuneScape\\plugins and reinstall. Settings are kept. On other systems use the plugins folder of your Jagex cache. Go to C:\\ProgramData\\Jagex\\RuneScape\\plugins and delete all the folders, which uninstalls all plugins, then reinstall. Saved settings stay. That solved it, thank you!", freq = "Often.", section = "G. Crashes and known issues", where = "#api-launch-known-issues, Oct 21; #plugin-support, Oct 21-23.", code = { "C:\\ProgramData\\Jagex\\RuneScape\\plugins" },
      posts = {
        { role = "Q", user = "Laidback LT", tag = "community", date = "Oct 21", lines = { "When I click Install on any plugin my game just crashes." } },
        { role = "A", user = "Rcm37", tag = "community", date = "Oct 21", lines = { "Really bad timing: they're having issues with plugins right now and are working on a fix." } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 21", lines = { "A hotfix was reverted. If you updated plugins between 15:00 and 16:00 BST, delete all folders (for example 6398181) under C:\\ProgramData\\Jagex\\RuneScape\\plugins and reinstall. Settings are kept. On other systems use the plugins folder of your Jagex cache." } },
        { role = "Q", user = "Sector", tag = "community", date = "Oct 23", lines = { "All my installed plugins have vanished. Is there a way to force a refresh of the hub or uninstall?" } },
        { role = "A", user = "Mod Jewel", tag = "Jagex staff", date = "Oct 23", lines = { "Go to C:\\ProgramData\\Jagex\\RuneScape\\plugins and delete all the folders, which uninstalls all plugins, then reinstall. Saved settings stay." } },
        { role = "A", user = "Sector", tag = "community", date = "Oct 23", lines = { "That solved it, thank you!" } } } },
    { n = 36, q = "Tile Markers: preset limits and crashes", a = "200 highlighted tiles in total, yes. Already expanded in a version that isn't released yet. Yes, 200. The Agility Helper would be enough, wouldn't it? Import strings have a size cap, so split big imports into smaller chunks. The shapes API also adds client memory over time. Known issue: some Tilemarkers preset names (the img text tag) can crash the client. Fixed Oct 21.", freq = "Often (5+).", section = "G. Crashes and known issues", where = "#plugin-support, Oct 19-21; #api-launch-known-issues, Oct 19-21.", code = {  },
      posts = {
        { role = "Q", user = "Zac", tag = "community", date = "Oct 21", lines = { "Is there a tile pack limit? Importing tile packs won't work unless I delete some." } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 21", lines = { "200 highlighted tiles in total, yes. Already expanded in a version that isn't released yet." } },
        { role = "Q", user = "Dracyn", tag = "community", date = "Oct 21", lines = { "What's the max tiles for agility presets?" } },
        { role = "A", user = "Grynjolf", tag = "community", date = "Oct 21", lines = { "Yes, 200. The Agility Helper would be enough, wouldn't it?" } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19-20", lines = { "Import strings have a size cap, so split big imports into smaller chunks. The shapes API also adds client memory over time." } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 19", lines = { "Known issue: some Tilemarkers preset names (the img text tag) can crash the client. Fixed Oct 21." } } } },
    { n = 37, q = "FPS loss and lag with plugins (e.g. Entity Hider, MES)", a = "Known issue: some plugins are causing FPS to decrease. A hotfix is planned. Test with displayfps, with and without the plugin and with players hidden. In one case hiding entities with Entity Hider fixed the lag from Menu Entry Swapper.", freq = "Several.", section = "G. Crashes and known issues", where = "#api-launch-known-issues, Oct 20; #plugin-support, Oct 19.", code = { "displayfps" },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Plugins are dropping my FPS and making the game lag." } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 20", lines = { "Known issue: some plugins are causing FPS to decrease. A hotfix is planned." } },
        { role = "A", user = "Unknown user", tag = "community", date = "Oct 19", lines = { "Test with displayfps, with and without the plugin and with players hidden. In one case hiding entities with Entity Hider fixed the lag from Menu Entry Swapper." } } } },
    { n = 38, q = "MiniMenu / left-click problems, Menu Entry Swapper limits", a = "Known issue: several left-click issues with the MiniMenu. Menu Entry Swapper limits are an API restriction by design (see #24); a fix is planned with no ETA.", freq = "Several.", section = "G. Crashes and known issues", where = "#api-launch-known-issues, Oct 19-20.", code = {  },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Left-click options are wrong with plugins on, and Menu Entry Swapper can't swap some options." } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 20", lines = { "Known issue: several left-click issues with the MiniMenu. Menu Entry Swapper limits are an API restriction by design (see #24); a fix is planned with no ETA." } } } },
    { n = 39, q = "Debug Menu plugin sent hit commands to every NPC", a = "Old bug, it defaulted to on for some reason. Just pushed the update.", freq = "Once.", section = "G. Crashes and known issues", where = "#plugin-support, Oct 21.", code = {  },
      posts = {
        { role = "Q", user = "Kogasa", tag = "community", date = "Oct 21", lines = { "The Debug Menu plugin started sending hit commands to every NPC around me." } },
        { role = "A", user = "Friendliness", tag = "community", date = "Oct 21", lines = { "Old bug, it defaulted to on for some reason. Just pushed the update." } } } },
    { n = 40, q = "Where's plugin X? Mobile? Release cadence?", a = "More plugins are in moderation (Clue Trainer, Ground Items and others) and will come in batches over the coming weeks; cadence to be confirmed. Plugins aren't on mobile yet. The Bank Utils plugin (in development-resources) will have that, compatible with PVME's preset maker. The Watchdog plugin should let you set that up. Not currently, but a dev said on stream that if you just start it again the log updates. They're aware of the request.", freq = "Often.", section = "G. Crashes and known issues", where = "#faq, Oct 19; #plugin-support, Oct 22.", code = {  },
      posts = {
        { role = "Q", user = "Unknown user", tag = "", date = "Oct 19", lines = { "Where's plugin X? Are plugins on mobile? How often do new plugins come out?" } },
        { role = "A", user = "Mod Light", tag = "Jagex staff", date = "Oct 19", lines = { "More plugins are in moderation (Clue Trainer, Ground Items and others) and will come in batches over the coming weeks; cadence to be confirmed. Plugins aren't on mobile yet." } },
        { role = "Q", user = "Hiraku Hiro", tag = "community", date = "Oct 22", lines = { "Can we look into equipment setups?" } },
        { role = "A", user = "Friendliness", tag = "community", date = "Oct 22", lines = { "The Bank Utils plugin (in development-resources) will have that, compatible with PVME's preset maker." } },
        { role = "Q", user = "SWITCHED", tag = "community", date = "Oct 22", lines = { "Is there a loot tracker that plays a sound for a specific drop?" } },
        { role = "A", user = "wandernaut", tag = "community", date = "Oct 22", lines = { "The Watchdog plugin should let you set that up." } },
        { role = "Q", user = "Doodel", tag = "community", date = "Oct 22", lines = { "Is there a way to replay Broken Home with Quest Helper?" } },
        { role = "A", user = "Aaron", tag = "community", date = "Oct 22", lines = { "Not currently, but a dev said on stream that if you just start it again the log updates. They're aware of the request." } } } },
}
